import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum UserRole {
  GUEST = 'GUEST',
  HOST = 'HOST',
  SUPERADMIN = 'SUPERADMIN'
}

export interface User {
  id: string;
  name: string;
  email: string;
  role: UserRole;
  avatar?: string;
  isOnline: boolean;
  isTyping?: boolean;
  hostId?: string; // If host, link to their unique panel
}

export interface Property {
  id: string;
  hostId: string;
  title: string;
  description: string;
  pricePerNight: number;
  location: string;
  category: string;
  images: string[];
  rating: number;
  reviewsCount: number;
  amenities: string[];
  maxGuests: number;
  status: 'available' | 'booked' | 'maintenance';
}

export interface Booking {
  id: string;
  propertyId: string;
  guestId: string;
  checkIn: string;
  checkOut: string;
  totalPrice: number;
  status: 'confirmed' | 'pending' | 'cancelled';
  guestsCount: number;
}

export interface ChatMessage {
  id: string;
  senderId: string;
  receiverId: string;
  text: string;
  timestamp: string;
}

export interface SiteConfig {
  heroTitle: string;
  heroSubtitle: string;
  heroBgImage: string;
  primaryColor: string;
  secondaryColor: string;
  enableSocialLogin: boolean;
}

import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getPropertyAiAdvice = async (propertyTitle: string, userNeeds: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `User is interested in "${propertyTitle}". They said: "${userNeeds}". 
      As a virtual travel concierge, explain why this property is a good fit for them or what they should know. 
      Keep it brief and encouraging (under 100 words).`,
    });
    return response.text;
  } catch (error) {
    console.error("Gemini Error:", error);
    return "I'm having trouble connecting to my AI brain right now, but this property looks lovely!";
  }
};

export const generateSmartDescription = async (details: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Based on these details: "${details}", write a catchy, vibrant property description for a vacation rental website. Include a few highlights.`,
    });
    return response.text;
  } catch (error) {
    console.error("Gemini Error:", error);
    return details;
  }
};

import React, { useState, useEffect, createContext, useContext } from 'react';
import { HashRouter, Routes, Route, Navigate, Link, useNavigate } from 'react-router-dom';
import { 
  Menu, X, Search, User, LogOut, LayoutDashboard, Heart, 
  MessageCircle, Moon, Sun, Filter, Star, MapPin, 
  ChevronRight, Calendar, CreditCard, PieChart, Plus, Settings, CheckCircle
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  UserRole, User as UserType, Property, SiteConfig, Booking 
} from './types';
import { 
  INITIAL_SITE_CONFIG, MOCK_USERS, MOCK_PROPERTIES 
} from './constants';

// --- Context ---
interface AppContextType {
  user: UserType | null;
  setUser: (u: UserType | null) => void;
  siteConfig: SiteConfig;
  setSiteConfig: (c: SiteConfig) => void;
  isDark: boolean;
  toggleTheme: () => void;
  bookings: Booking[];
  addBooking: (b: Booking) => void;
  properties: Property[];
  setProperties: React.Dispatch<React.SetStateAction<Property[]>>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

// --- Components ---

const Navbar = () => {
  const { user, setUser, isDark, toggleTheme } = useApp();
  const navigate = useNavigate();

  return (
    <nav className="sticky top-0 z-50 glass-card border-b border-slate-200 dark:border-slate-800 px-4 py-3">
      <div className="max-w-7xl mx-auto flex items-center justify-between">
        <Link to="/" className="text-2xl font-extrabold tracking-tight flex items-center gap-2">
          <span className="bg-gradient-to-r from-indigo-600 to-pink-500 bg-clip-text text-transparent">HAVENLY</span>
        </Link>

        <div className="hidden md:flex items-center gap-6">
          <Link to="/" className="text-sm font-medium hover:text-indigo-600 transition-colors">Explore</Link>
          <button onClick={toggleTheme} className="p-2 rounded-full hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors">
            {isDark ? <Sun size={20} /> : <Moon size={20} />}
          </button>

          {user ? (
            <div className="flex items-center gap-4">
              <Link to="/chat" className="p-2 rounded-full hover:bg-slate-100 dark:hover:bg-slate-800 relative">
                <MessageCircle size={20} />
                <span className="absolute top-0 right-0 w-2 h-2 bg-pink-500 rounded-full"></span>
              </Link>
              <div className="group relative">
                <button className="flex items-center gap-2 p-1 pl-3 rounded-full border border-slate-200 dark:border-slate-700 hover:shadow-md transition-shadow">
                  <span className="text-xs font-semibold">{user.name}</span>
                  <img src={user.avatar} className="w-8 h-8 rounded-full border border-slate-200" alt="avatar" />
                </button>
                <div className="absolute right-0 top-full mt-2 w-48 glass-card border rounded-xl overflow-hidden shadow-xl opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all">
                  <Link to="/dashboard" className="flex items-center gap-2 px-4 py-2 hover:bg-slate-50 dark:hover:bg-slate-800 text-sm">
                    <LayoutDashboard size={16} /> Dashboard
