const PropertyDetailPage = () => {
  const { id } = useParams<{ id: string }>();
  const { properties, addBooking, user } = useApp();
  const navigate = useNavigate();
  const property = properties.find(p => p.id === id);
  const [isBooking, setIsBooking] = useState(false);

  if (!property) return <div className="p-20 text-center">Property not found</div>;

  const handleBooking = () => {
    if (!user) {
      navigate('/login');
      return;
    }
    setIsBooking(true);
    setTimeout(() => {
      addBooking({
        id: Math.random().toString(36).substr(2, 9),
        propertyId: property.id,
        guestId: user.id,
        checkIn: '2024-12-20',
        checkOut: '2024-12-25',
        totalPrice: property.pricePerNight * 5,
        status: 'confirmed',
        guestsCount: 2
      });
      setIsBooking(false);
      navigate('/dashboard');
    }, 1500);
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-12">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
        {/* Gallery & Content */}
        <div className="lg:col-span-2">
          <h1 className="text-4xl font-extrabold mb-6">{property.title}</h1>
          <div className="grid grid-cols-2 gap-4 h-[500px] mb-8">
            <div className="col-span-2 md:col-span-1 rounded-3xl overflow-hidden h-full">
              <img src={property.images[0]} className="w-full h-full object-cover" alt="main" />
            </div>
            <div className="hidden md:grid grid-rows-2 gap-4 h-full">
              <div className="rounded-3xl overflow-hidden h-full">
                <img src={property.images[1] || property.images[0]} className="w-full h-full object-cover" alt="sec" />
              </div>
              <div className="rounded-3xl overflow-hidden bg-slate-200 flex items-center justify-center text-slate-500 font-bold">
                View All 15 Photos
              </div>
            </div>
          </div>

          <div className="flex items-center gap-8 border-b pb-8 mb-8">
            <div className="flex items-center gap-2">
              <MapPin size={20} className="text-indigo-600" />
              <span className="font-semibold">{property.location}</span>
            </div>
            <div className="flex items-center gap-2">
              <User size={20} className="text-indigo-600" />
              <span className="font-semibold">{property.maxGuests} Guests max</span>
            </div>
          </div>

          <h2 className="text-2xl font-bold mb-4">About this place</h2>
          <p className="text-slate-600 dark:text-slate-400 leading-relaxed text-lg mb-8">
            {property.description}
