  if (!user) return <Navigate to="/login" />;

  // Multi-tenant conditional views
  const isSuper = user.role === UserRole.SUPERADMIN;
  const isHost = user.role === UserRole.HOST;

  return (
    <div className="max-w-7xl mx-auto px-4 py-12 flex flex-col md:flex-row gap-12">
      {/* Sidebar Nav */}
