                  <input 
                    type="text" 
                    value={siteConfig.heroBgImage}
                    onChange={(e) => setSiteConfig({...siteConfig, heroBgImage: e.target.value})}
                    className="w-full p-4 rounded-xl bg-slate-50 dark:bg-slate-900 border"
                  />
