// Fix: Making children optional to resolve TS error when children are passed as elements inside JSX
const AppProvider = ({ children }: { children?: React.ReactNode }) => {
  const [user, setUser] = useState<UserType | null>(null);
  const [siteConfig, setSiteConfig] = useState<SiteConfig>(INITIAL_SITE_CONFIG);
  const [isDark, setIsDark] = useState(false);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [properties, setProperties] = useState<Property[]>(MOCK_PROPERTIES);

  useEffect(() => {
    if (window.matchMedia('(prefers-color-scheme: dark)').matches) {
      setIsDark(true);
    }
  }, []);

  useEffect(() => {
    if (isDark) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDark]);

  const toggleTheme = () => setIsDark(!isDark);
  const addBooking = (b: Booking) => setBookings([...bookings, b]);

  return (
    <AppContext.Provider value={{ 
      user, setUser, siteConfig, setSiteConfig, 
      isDark, toggleTheme, bookings, addBooking,
      properties, setProperties
    }}>
      {children}
    </AppContext.Provider>
  );
};

