const PropertyDetailPage = () => {
  const { id } = useParams<{ id: string }>();
  const { properties, setBookings, user } = useApp();
  const navigate = useNavigate();
  const property = properties.find(p => p.id === id);
  const [isBooking, setIsBooking] = useState(false);
  const [aiAdvice, setAiAdvice] = useState<string | null>(null);

  useEffect(() => {
    if (property) {
      getPropertyAiAdvice(property.title, "I'm looking for a quiet family-friendly place for 1 week.").then(setAiAdvice);
    }
  }, [property]);

  if (!property) return <div className="p-20 text-center">Propiedad no encontrada</div>;

  const handleBooking = () => {
    if (!user) { navigate('/login'); return; }
    setIsBooking(true);
    setTimeout(() => {
      const tax = property.pricePerNight * 5 * 0.0625;
      const commission = property.pricePerNight * 5 * 0.1;
      setBookings(prev => [...prev, {
        id: Math.random().toString(36).substr(2, 9),
        propertyId: property.id,
        guestId: user.id,
        checkIn: '2024-12-20',
        checkOut: '2024-12-25',
        totalPrice: property.pricePerNight * 5 + tax,
        taxAmount: tax,
        commissionAmount: commission,
        status: 'pending',
        guestsCount: 2
      }]);
      setIsBooking(false);
      navigate('/profile');
    }, 1500);
  };

  return (
    <div className="max-w-[1440px] mx-auto px-6 py-12">
