const PropertyDetailPage = () => {
  const { id } = useParams<{ id: string }>();
  const { properties, setBookings, user, verifications, addVerification } = useApp();
  const navigate = useNavigate();
  const property = properties.find(p => p.id === id);
  const [showPayment, setShowPayment] = useState(false);
  const [currentBooking, setCurrentBooking] = useState<Booking | null>(null);

  if (!property) return <div className="p-20 text-center">Propiedad no encontrada</div>;

  // Complex Identity Check
  const verification = verifications.find(v => v.userId === user?.id && v.hostId === property.hostId);
  const isVerifiedForThisHost = verification?.status === 'approved';
  const isPendingVerification = verification?.status === 'pending';

  const handleBookingClick = () => {
    if (!user) { navigate('/login'); return; }

    if (!isVerifiedForThisHost) {
      if (isPendingVerification) {
        alert('Tu solicitud de verificación para este host está pendiente de revisión manual.');
      } else {
        // Mock Identity Upload for this specific host
        addVerification({
          id: Math.random().toString(36).substr(2, 9),
          userId: user.id,
          hostId: property.hostId,
          status: 'pending',
          documentUrl: 'mock_doc_path.jpg',
          submittedAt: new Date().toISOString()
        });
        alert(`Solicitud enviada al Host del inmueble. Deben aprobarte manualmente para permitir la renta.`);
      }
      return;
    }

    const tax = property.pricePerNight * 5 * 0.0625;
    const commission = property.pricePerNight * 5 * 0.1;
    const newBooking: Booking = {
      id: Math.random().toString(36).substr(2, 9),
      propertyId: property.id,
      guestId: user.id,
      checkIn: '2024-12-20',
      checkOut: '2024-12-25',
      totalPrice: property.pricePerNight * 5 + tax,
      taxAmount: tax,
      commissionAmount: commission,
      status: 'pending',
      guestsCount: 2
    };
    setCurrentBooking(newBooking);
    setShowPayment(true);
  };

  const handlePaymentSuccess = () => {
    if (currentBooking) {
      setBookings(prev => [...prev, { ...currentBooking, status: 'paid' }]);
      setShowPayment(false);
      navigate('/profile');
    }
  };

  return (
    <div className="max-w-[1440px] mx-auto px-6 py-12">
      <div className="flex items-start justify-between mb-8">
        <div>
          <h1 className="text-4xl md:text-5xl font-black mb-4">{property.title}</h1>
          <div className="flex items-center gap-6 text-slate-500 font-bold text-sm">
            <div className="flex items-center gap-2">
              <Star size={18} className="fill-yellow-400 text-yellow-400" />
              <span>{property.rating} ({property.reviewsCount} reseñas)</span>
            </div>
            <div className="flex items-center gap-2">
              <MapPin size={18} />
              <span>{property.location}</span>
            </div>
            {isVerifiedForThisHost ? (
              <span className="text-green-500 flex items-center gap-1"><ShieldCheck size={16}/> Verificado para este Host</span>
            ) : (
              <span className="text-orange-500 flex items-center gap-1"><ShieldAlert size={16}/> Requiere verificación de Host</span>
            )}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-4 grid-rows-2 gap-4 h-[600px] mb-12 rounded-[2.5rem] overflow-hidden">
        <div className="col-span-2 row-span-2"><img src={property.images[0]} className="w-full h-full object-cover" /></div>
        <div className="col-span-1 row-span-1"><img src={property.images[1] || property.images[0]} className="w-full h-full object-cover" /></div>
        <div className="col-span-1 row-span-1"><img src={property.images[2] || property.images[0]} className="w-full h-full object-cover" /></div>
        <div className="col-span-2 row-span-1 relative">
          <img src={property.images[0]} className="w-full h-full object-cover brightness-[0.4]" />
          <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
            <span className="text-white text-xl font-black">+12 fotos</span>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-16">
        <div className="lg:col-span-2">
          <h2 className="text-3xl font-black mb-6">Sobre este lugar</h2>
          <p className="text-slate-500 text-lg leading-relaxed mb-10">{property.description}</p>
        </div>
        <div className="lg:col-span-1">
          <div className="sticky top-28 glass-card p-10 rounded-[2.5rem] shadow-2xl border-white dark:border-slate-800">
             <div className="flex items-baseline gap-1 mb-8">
               <span className="text-4xl font-black text-pink-500">€{property.pricePerNight}</span>
               <span className="text-slate-400 font-bold">/ noche</span>
             </div>
             <button onClick={handleBookingClick} className="w-full py-5 rounded-2xl bg-gradient-to-r from-pink-500 to-indigo-600 text-white font-black text-lg shadow-xl hover:scale-[1.02] active:scale-[0.98] transition-all">
               Reservar Ahora
             </button>
             {!isVerifiedForThisHost && <p className="text-xs text-orange-600 font-bold mt-4 text-center">Debes verificar tu identidad con este Host antes de pagar.</p>}
          </div>
        </div>
      </div>

      {showPayment && currentBooking && <PaymentModal booking={currentBooking} onComplete={handlePaymentSuccess} onCancel={() => setShowPayment(false)} />}
    </div>
  );
};

