const AdminVerifications = () => {
  const { user, verifications, updateVerification, allUsers } = useApp();
  const filteredVerifications = user?.role === UserRole.SUPERADMIN ? verifications : verifications.filter(v => v.hostId === user?.id);

  return (
    <div className="flex-1 p-12 bg-slate-50/50 dark:bg-slate-950/50 overflow-y-auto">
