          <div className="text-center py-20 glass-card rounded-[2rem] text-slate-400 font-bold border-dashed border-2">No hay solicitudes pendientes.</div>
        ) : (
          filteredVerifications.map(v => {
            const requester = allUsers.find(u => u.id === v.userId);
            return (
              <div key={v.id} className="glass-card p-8 rounded-[2rem] border flex items-center justify-between shadow-xl">
                <div className="flex items-center gap-6">
                  <img src={requester?.avatar} className="w-16 h-16 rounded-full ring-4 ring-slate-100" />
                  <div>
                    <h3 className="text-xl font-bold">{requester?.name}</h3>
                    <p className="text-slate-400 text-sm font-medium">Solicitud ID: {v.id}</p>
                    <span className={`text-[10px] font-black uppercase px-2 py-1 rounded-lg mt-2 inline-block ${v.status === 'pending' ? 'bg-orange-100 text-orange-600' : 'bg-green-100 text-green-600'}`}>{v.status}</span>
                  </div>
                </div>
                <div className="flex gap-4">
                  <button className="px-6 py-2.5 rounded-xl border-2 font-black text-xs hover:bg-slate-50">Ver Documento</button>
                  {v.status === 'pending' && (
                    <>
                      <button onClick={() => updateVerification(v.id, 'approved')} className="px-6 py-2.5 rounded-xl bg-green-500 text-white font-black text-xs shadow-lg shadow-green-500/20">Aprobar</button>
                      <button onClick={() => updateVerification(v.id, 'rejected')} className="px-6 py-2.5 rounded-xl bg-red-500 text-white font-black text-xs shadow-lg shadow-red-500/20">Rechazar</button>
                    </>
                  )}
                </div>
              </div>
            );
