                <Route path="verifications" element={<AdminVerifications />} />
                <Route path="chat" element={<ChatPage />} />
                <Route path="config" element={<div className="p-12 font-bold text-slate-400">Configuración Avanzada (Proximamente)</div>} />
                <Route path="*" element={<Navigate to="/admin" />} />
              </Routes>
            </div>
          } />
          <Route path="*" element={
            <div className="min-h-screen transition-colors duration-300 dark:bg-slate-950 dark:text-slate-100">
              <Navbar />
              <Routes>
                <Route path="/" element={<LandingPage />} />
                <Route path="/property/:id" element={<PropertyDetailPage />} />
                <Route path="/settings" element={<SettingsPage />} />
                <Route path="/login" element={<AuthPage mode="login" />} />
