const AdminBookings = () => {
  const { bookings, properties } = useApp();
  const [filter, setFilter] = useState<'Todas' | 'Pendientes' | 'Aprobadas' | 'Pagadas'>('Todas');

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'paid': return 'bg-green-100 text-green-600';
      case 'approved': return 'bg-blue-100 text-blue-600';
      case 'pending': return 'bg-orange-100 text-orange-600';
      default: return 'bg-slate-100 text-slate-600';
    }
  };

  const filteredBookings = bookings.filter(b => {
    if (filter === 'Todas') return true;
    if (filter === 'Pendientes') return b.status === 'pending';
    if (filter === 'Aprobadas') return b.status === 'approved';
    if (filter === 'Pagadas') return b.status === 'paid';
    return true;
  });

  return (
    <div className="flex-1 p-12 bg-slate-50/50 dark:bg-slate-950/50 overflow-y-auto">
      <h1 className="text-4xl font-black mb-12">Gestión de Reservas</h1>

      <div className="grid grid-cols-4 gap-8 mb-12">
        <button onClick={() => setFilter('Pendientes')} className="glass-card p-8 rounded-[2rem] border shadow-lg text-center hover:scale-105 transition-transform">
          <p className="text-slate-400 font-black text-[10px] mb-2 uppercase tracking-widest">Pendientes</p>
          <div className="flex items-center justify-center gap-2">
            <Clock size={20} className="text-orange-500" />
            <p className="text-3xl font-black">{bookings.filter(b => b.status === 'pending').length}</p>
          </div>
        </button>
        <button onClick={() => setFilter('Aprobadas')} className="glass-card p-8 rounded-[2rem] border shadow-lg text-center hover:scale-105 transition-transform">
          <p className="text-slate-400 font-black text-[10px] mb-2 uppercase tracking-widest">Aprobadas</p>
          <div className="flex items-center justify-center gap-2">
            <CheckSquare size={20} className="text-blue-500" />
            <p className="text-3xl font-black">{bookings.filter(b => b.status === 'approved').length}</p>
          </div>
        </button>
        <button onClick={() => setFilter('Pagadas')} className="glass-card p-8 rounded-[2rem] border shadow-lg text-center hover:scale-105 transition-transform">
          <p className="text-slate-400 font-black text-[10px] mb-2 uppercase tracking-widest">Pagadas</p>
          <div className="flex items-center justify-center gap-2">
            <CheckCircle size={20} className="text-green-500" />
            <p className="text-3xl font-black">{bookings.filter(b => b.status === 'paid').length}</p>
          </div>
        </button>
        <div className="glass-card p-8 rounded-[2rem] border shadow-lg text-center">
          <p className="text-slate-400 font-black text-[10px] mb-2 uppercase tracking-widest">Total Ingresos</p>
          <div className="flex items-center justify-center gap-2">
            <Calendar size={20} className="text-pink-500" />
            <p className="text-3xl font-black">€{bookings.reduce((a, b) => a + b.totalPrice, 0).toFixed(0)}</p>
          </div>
        </div>
      </div>

      <div className="flex gap-4 mb-8">
        {['Todas', 'Pendientes', 'Aprobadas', 'Pagadas'].map(t => (
          <button key={t} onClick={() => setFilter(t as any)} className={`px-8 py-3 rounded-full font-bold text-sm transition-all border ${filter === t ? 'bg-pink-500 border-pink-500 text-white shadow-lg' : 'bg-white dark:bg-slate-900 border-slate-100 dark:border-slate-800'}`}>{t}</button>
        ))}
      </div>

      <div className="space-y-6">
        {filteredBookings.map(b => {
          const property = properties.find(p => p.id === b.propertyId);
          return (
            <div key={b.id} className="glass-card p-8 rounded-[2.5rem] border shadow-xl flex items-center justify-between group cursor-pointer hover:border-pink-500 transition-colors">
              <div className="flex items-center gap-6">
                <img src={property?.images[0]} className="w-24 h-16 rounded-2xl object-cover" />
                <div>
                  <h3 className="text-xl font-bold">{property?.title}</h3>
                  <p className="text-slate-400 font-medium text-sm"><MapPin size={12} className="inline mr-1"/>{property?.location}</p>
                  <div className="flex gap-8 mt-4">
                    <div><p className="text-[10px] font-black uppercase text-slate-400">Check-in</p><p className="text-sm font-bold">{b.checkIn}</p></div>
                    <div><p className="text-[10px] font-black uppercase text-slate-400">Check-out</p><p className="text-sm font-bold">{b.checkOut}</p></div>
                    <div><p className="text-[10px] font-black uppercase text-slate-400">Huéspedes</p><p className="text-sm font-bold">{b.guestsCount}</p></div>
                  </div>
                </div>
              </div>
              <div className="text-right">
                <p className="text-2xl font-black mb-2">€{b.totalPrice.toFixed(0)}</p>
                <span className={`px-4 py-1 rounded-full text-[10px] font-black uppercase tracking-widest ${getStatusColor(b.status)}`}>{b.status}</span>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

