                className={`flex flex-col ${isMe ? 'items-end' : 'items-start'}`}
               >
                 <div className={`max-w-[75%] p-4 rounded-3xl shadow-sm relative group ${
                   isMe 
                   ? 'bg-gradient-to-r from-pink-500 to-indigo-600 text-white rounded-tr-none' 
                   : 'bg-white dark:bg-slate-800 text-slate-800 dark:text-slate-200 rounded-tl-none border border-slate-100 dark:border-slate-700'
                 }`}>
                   <p className="font-medium text-sm leading-relaxed">{msg.text}</p>
                   {msg.type === 'doc' && msg.fileUrl && (
                     <a href={msg.fileUrl} target="_blank" rel="noreferrer" className="mt-2 flex items-center gap-2 p-2 bg-black/10 rounded-xl text-xs font-bold hover:bg-black/20 transition-colors">
                       <Upload size={14} /> Abrir Documento
                     </a>
                   )}
                   <span className={`text-[10px] font-bold absolute bottom-[-20px] ${isMe ? 'right-1 text-slate-400' : 'left-1 text-slate-400'} uppercase`}>
                     {msg.timestamp}
                   </span>
                 </div>
               </motion.div>
             );
           })}
           {isTyping && (
             <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex flex-col items-start">
               <div className="bg-white dark:bg-slate-800 p-4 rounded-3xl rounded-tl-none border border-slate-100 dark:border-slate-700 flex gap-1">
