                 <span className="w-1.5 h-1.5 bg-slate-300 rounded-full animate-bounce delay-100"></span>
                 <span className="w-1.5 h-1.5 bg-slate-300 rounded-full animate-bounce delay-200"></span>
               </div>
             </motion.div>
           )}
        </div>

        {/* Chat Input */}
        <div className="p-6 border-t border-slate-100 dark:border-slate-800 bg-white/50 dark:bg-slate-900/50 backdrop-blur-md">
          <form onSubmit={handleSend} className="flex items-center gap-4 bg-slate-50 dark:bg-slate-800 p-2 rounded-3xl border border-slate-200 dark:border-slate-700 transition-all focus-within:ring-4 ring-pink-500/10">
            <input 
              type="file" 
              ref={fileInputRef} 
              className="hidden" 
              onChange={handleFileUpload}
            />
            <button 
              type="button"
              onClick={() => fileInputRef.current?.click()}
              className="p-3 rounded-2xl hover:bg-white dark:hover:bg-slate-700 transition-colors text-slate-400 hover:text-pink-500"
              title="Adjuntar archivo"
            >
              <AttachmentIcon size={20} />
            </button>
            <button 
              type="button"
              className="p-2 rounded-2xl hover:bg-white dark:hover:bg-slate-700 transition-colors text-slate-400 hover:text-indigo-500"
              title="Emoji"
            >
              <Smile size={20} />
            </button>
            <input 
              type="text" 
              placeholder="Escribe un mensaje..." 
              value={inputText}
              onChange={e => setInputText(e.target.value)}
              className="flex-1 bg-transparent border-none outline-none font-medium text-sm px-2 text-slate-900 dark:text-white placeholder:text-slate-400" 
            />
            <button 
              type="submit"
              disabled={!inputText.trim()}
              className="bg-pink-500 text-white p-4 rounded-2xl shadow-lg hover:bg-pink-600 transition-all active:scale-95 disabled:opacity-50 disabled:grayscale disabled:scale-100"
            >
              <Send size={20} />
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

