const AdminBookings = () => {
  const { bookings, properties } = useApp();
  const [filter, setFilter] = useState<'Todas' | 'Pendientes' | 'Aprobadas' | 'Pagadas'>('Todas');

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'paid': return 'bg-green-100 text-green-600';
      case 'approved': return 'bg-blue-100 text-blue-600';
      case 'pending': return 'bg-orange-100 text-orange-600';
      default: return 'bg-slate-100 text-slate-600';
    }
  };

  const filteredBookings = bookings.filter(b => {
    if (filter === 'Todas') return true;
    if (filter === 'Pendientes') return b.status === 'pending';
    if (filter === 'Aprobadas') return b.status === 'approved';
    if (filter === 'Pagadas') return b.status === 'paid';
    return true;
  });

  return (
    <div className="flex-1 p-12 bg-slate-50/50 dark:bg-slate-950/50 overflow-y-auto">
      <h1 className="text-4xl font-black mb-12">Gestión de Reservas</h1>

