const PropertyDetailPage = () => {
  const { id } = useParams();
  const { properties, setBookings, setProperties } = useApp();
  const navigate = useNavigate();

  // Component States
  const [advice, setAdvice] = useState<string | null>(null);
  const [loadingAdvice, setLoadingAdvice] = useState(false);
  const [userNeeds, setUserNeeds] = useState('');

  const [lightbox, setLightbox] = useState({ isOpen: false, index: 0 });
  const [checkIn, setCheckIn] = useState('2024-06-15');
  const [checkOut, setCheckOut] = useState('2024-06-20');
  const [guests, setGuests] = useState(2);

  const property = properties.find(p => p.id === id);
  if (!property) return <div className="p-20 text-center font-bold">Propiedad no encontrada</div>;

  const nightsCount = Math.max(1, Math.ceil((new Date(checkOut).getTime() - new Date(checkIn).getTime()) / (1000 * 3600 * 24)));
  const totalBasePrice = property.pricePerNight * nightsCount;
  const taxes = totalBasePrice * property.taxRate;
  const totalFinalPrice = totalBasePrice + taxes;

  const handleGetAdvice = async () => {
    if (!userNeeds.trim()) return;
    setLoadingAdvice(true);
    const res = await getPropertyAiAdvice(property.title, userNeeds);
    setAdvice(res);
    setLoadingAdvice(false);
  };

  const handleBook = () => {
    const booking: Booking = {
      id: Math.random().toString(36).substr(2, 9),
      propertyId: property.id,
      guestId: 'u1',
      checkIn,
      checkOut,
      totalPrice: totalFinalPrice,
      taxAmount: taxes,
      commissionAmount: 0,
      status: 'pending',
      guestsCount: guests
    };
    setBookings(prev => [...prev, booking]);
    navigate('/admin/bookings');
  };

  const handleShare = () => {
    if (navigator.share) {
      navigator.share({
        title: property.title,
        text: property.description,
        url: window.location.href,
      }).catch(console.error);
    } else {
      navigator.clipboard.writeText(window.location.href);
      alert("Enlace copiado al portapapeles");
    }
  };

  const toggleFavorite = () => {
    setProperties(prev => prev.map(p => p.id === property.id ? { ...p, isWatchlisted: !p.isWatchlisted } : p));
  };

  return (
    <div className="max-w-[1440px] mx-auto px-6 py-12 pb-20 animate-in fade-in duration-700">
