            <span className="flex items-center gap-1 underline cursor-pointer"><Star size={16} className="text-yellow-400 fill-yellow-400" /> {property.rating} ({property.reviewsCount} reseñas)</span>
            <span className="flex items-center gap-1 underline cursor-pointer"><MapPin size={16} /> {property.location}</span>
          </div>
        </div>
        <div className="flex items-center gap-4">
          <button onClick={handleShare} className="flex items-center gap-2 px-6 py-2.5 rounded-xl border-2 hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors font-bold"><Share size={18} /> Compartir</button>
          <button onClick={toggleFavorite} className="flex items-center gap-2 px-6 py-2.5 rounded-xl border-2 hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors font-bold">
            <Heart size={18} className={property.isWatchlisted ? 'fill-pink-500 text-pink-500' : ''} /> 
            {property.isWatchlisted ? 'Guardado' : 'Guardar'}
