            <input 
              type="text" 
              placeholder="Buscar conversaciones..." 
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
              className="w-full py-3.5 pl-12 pr-4 rounded-2xl bg-slate-50 dark:bg-slate-800 border-none outline-none font-medium text-sm transition-all focus:ring-2 ring-pink-500/20" 
            />
          </div>
        </div>
        <div className="flex-1 overflow-y-auto custom-scrollbar">
          {filteredThreads.map(thread => (
            <button 
              key={thread.id} 
              onClick={() => setActiveThreadId(thread.id)}
              className={`w-full p-6 flex items-center gap-4 hover:bg-white dark:hover:bg-slate-800 transition-all border-b border-slate-50/50 dark:border-slate-800/50 relative ${activeThreadId === thread.id ? 'bg-white dark:bg-slate-800 shadow-md z-10' : ''}`}
            >
              <div className="relative">
                <img src={thread.avatar} className="w-14 h-14 rounded-full object-cover shadow-md" alt={thread.name} />
                <span className={`absolute bottom-0 right-0 w-3.5 h-3.5 border-2 border-white dark:border-slate-800 rounded-full ${thread.status === 'En línea' ? 'bg-green-500' : 'bg-slate-300'}`}></span>
              </div>
              <div className="flex-1 text-left min-w-0">
                <div className="flex items-center justify-between mb-1">
                  <h4 className="font-bold text-slate-900 dark:text-white truncate">{thread.name}</h4>
                  <span className="text-[10px] font-bold text-slate-400 uppercase whitespace-nowrap">{thread.time}</span>
