           )}
        </div>

        <div className="p-6 border-t border-slate-100 dark:border-slate-800 bg-white/50 dark:bg-slate-900/50 backdrop-blur-md">
          <form onSubmit={handleSend} className="flex items-center gap-4 bg-slate-50 dark:bg-slate-800 p-2 rounded-3xl border border-slate-200 dark:border-slate-700">
            <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileUpload} />
