                  <button onClick={handleVerify} disabled={isVerifying} className="bg-white dark:bg-slate-800 px-8 py-3 rounded-xl border shadow-sm font-black text-sm hover:shadow-md transition-all">
                    {isVerifying ? 'Procesando...' : 'Subir Documento'}
                  </button>
               </div>
             )}
          </div>
        </div>
      </div>
    </div>
  );
};

