        </button>
        <button onClick={() => setFilter('Pagadas')} className="glass-card p-8 rounded-[2rem] border shadow-lg text-center hover:scale-105 transition-transform dark:border-none">
          <p className="text-slate-400 font-black text-[10px] mb-2 uppercase tracking-widest">Pagadas</p>
          <div className="flex items-center justify-center gap-2">
            <CheckCircle size={20} className="text-green-500" />
