          <button type="submit" className="w-full py-4 rounded-2xl bg-pink-500 text-white font-black text-lg shadow-xl hover:bg-pink-600 transition-all active:scale-95">{mode === 'login' ? 'Entrar' : 'Registrarse'}</button>
        </form>
      </motion.div>
    </div>
  );
};

const AdminVerifications = () => {
  const { verifications, allUsers, updateVerification } = useApp();
