      { id: 'm3', senderId: 'u2', text: 'Sí, disponemos de cuna y trona si lo necesitas.', timestamp: '18:31', type: 'text' },
    ],
    '2': [ { id: 'm4', senderId: 'u3', text: 'Bienvenido a StayHub, ¿alguna duda?', timestamp: '10:00', type: 'text' } ],
    '3': [ { id: 'm5', senderId: 'u4', text: 'Gracias por tu reserva.', timestamp: 'Yesterday', type: 'text' } ]
  });

  const activeThread = threads.find(t => t.id === activeThreadId);
  const activeMessages = messages[activeThreadId] || [];

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [activeMessages, isTyping]);

  const handleSend = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!inputText.trim()) return;

    const newMessage: ChatMessage = {
      id: Math.random().toString(36).substr(2, 9),
      senderId: user?.id || 'u1',
      text: inputText,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      type: 'text'
    };

    setMessages(prev => ({
      ...prev,
      [activeThreadId]: [...(prev[activeThreadId] || []), newMessage]
    }));
    setInputText('');

    setTimeout(() => {
      setIsTyping(true);
      setTimeout(() => {
        setIsTyping(false);
        const reply: ChatMessage = {
          id: Math.random().toString(36).substr(2, 9),
          senderId: activeThread?.participantId || 'bot',
          text: `Entendido. Revisaré tu mensaje sobre "${newMessage.text}" y te responderé en breve.`,
          timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
          type: 'text'
        };
        setMessages(prev => ({
          ...prev,
          [activeThreadId]: [...(prev[activeThreadId] || []), reply]
        }));
      }, 2000);
    }, 1000);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const newMessage: ChatMessage = {
        id: Math.random().toString(36).substr(2, 9),
        senderId: user?.id || 'u1',
        text: `Archivo enviado: ${file.name}`,
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        type: 'doc',
        fileUrl: URL.createObjectURL(file)
      };
      setMessages(prev => ({
        ...prev,
        [activeThreadId]: [...(prev[activeThreadId] || []), newMessage]
      }));
    }
  };

  const filteredThreads = threads.filter(t => 
    t.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    t.lastMessage.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="max-w-[1440px] mx-auto px-6 py-12 flex gap-8 h-[calc(100vh-100px)] animate-in fade-in duration-500">
      <div className="w-1/3 glass-card rounded-[2.5rem] border shadow-2xl flex flex-col overflow-hidden bg-white/40 dark:bg-slate-900/40">
        <div className="p-8 border-b border-slate-100 dark:border-slate-800">
          <h2 className="text-2xl font-black mb-6">Mensajes</h2>
          <div className="relative group">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-pink-500 transition-colors" size={18} />
            <input 
              type="text" 
              placeholder="Buscar conversaciones..." 
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
              className="w-full py-3.5 pl-12 pr-4 rounded-2xl bg-slate-50 dark:bg-slate-800 border-none outline-none font-medium text-sm transition-all focus:ring-2 ring-pink-500/20" 
            />
          </div>
        </div>
        <div className="flex-1 overflow-y-auto custom-scrollbar">
          {filteredThreads.map(thread => (
            <button 
              key={thread.id} 
              onClick={() => setActiveThreadId(thread.id)}
              className={`w-full p-6 flex items-center gap-4 hover:bg-white dark:hover:bg-slate-800 transition-all border-b border-slate-50/50 dark:border-slate-800/50 relative ${activeThreadId === thread.id ? 'bg-white dark:bg-slate-800 shadow-md z-10' : ''}`}
            >
              <div className="relative">
                <img src={thread.avatar} className="w-14 h-14 rounded-full object-cover shadow-md" alt={thread.name} />
                <span className={`absolute bottom-0 right-0 w-3.5 h-3.5 border-2 border-white dark:border-slate-800 rounded-full ${thread.status === 'En línea' ? 'bg-green-500' : 'bg-slate-300'}`}></span>
              </div>
              <div className="flex-1 text-left min-w-0">
                <div className="flex items-center justify-between mb-1">
                  <h4 className="font-bold text-slate-900 dark:text-white truncate">{thread.name}</h4>
                  <span className="text-[10px] font-bold text-slate-400 uppercase whitespace-nowrap">{thread.time}</span>
                </div>
                <p className="text-sm text-slate-500 font-medium truncate">{thread.lastMessage}</p>
              </div>
              {thread.unread > 0 && <span className="w-5 h-5 bg-pink-500 text-white text-[10px] font-black rounded-full flex items-center justify-center shrink-0">{thread.unread}</span>}
            </button>
          ))}
        </div>
      </div>

      <div className="flex-1 glass-card rounded-[2.5rem] border shadow-2xl flex flex-col overflow-hidden bg-white/60 dark:bg-slate-900/60">
        <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-white/50 dark:bg-slate-900/50 backdrop-blur-md">
          <div className="flex items-center gap-4">
            <div className="relative">
              <img src={activeThread?.avatar} className="w-12 h-12 rounded-full object-cover shadow-lg" alt={activeThread?.name} />
              <span className={`absolute bottom-0 right-0 w-3 h-3 border-2 border-white rounded-full ${activeThread?.status === 'En línea' ? 'bg-green-500' : 'bg-slate-300'}`}></span>
            </div>
            <div>
              <h3 className="font-bold text-lg">{activeThread?.name}</h3>
              <p className={`text-[10px] font-black uppercase tracking-widest ${isTyping ? 'text-pink-500 animate-pulse' : 'text-green-500'}`}>
                {isTyping ? 'Escribiendo...' : activeThread?.status}
              </p>
            </div>
          </div>
          <div className="flex items-center gap-3">
             <button onClick={() => alert(`Llamada...`)} className="p-3 rounded-xl bg-slate-50 dark:bg-slate-800 text-slate-600 dark:text-slate-400 hover:text-pink-500 transition-all"><Phone size={20} /></button>
             <button onClick={() => alert(`Video...`)} className="p-3 rounded-xl bg-slate-50 dark:bg-slate-800 text-slate-600 dark:text-slate-400 hover:text-pink-500 transition-all"><Video size={20} /></button>
             <button onClick={() => setShowOptions(!showOptions)} className="p-3 rounded-xl bg-slate-50 dark:bg-slate-800 text-slate-600 dark:text-slate-400 hover:text-pink-500 transition-all"><MoreVertical size={20} /></button>
          </div>
        </div>

        <div ref={scrollRef} className="flex-1 p-8 overflow-y-auto space-y-6 custom-scrollbar bg-slate-50/30 dark:bg-slate-900/30">
           {activeMessages.map((msg) => {
             const isMe = msg.senderId === (user?.id || 'u1');
             return (
               <motion.div key={msg.id} initial={{ opacity: 0, x: isMe ? 20 : -20 }} animate={{ opacity: 1, x: 0 }} className={`flex flex-col ${isMe ? 'items-end' : 'items-start'}`}>
                 <div className={`max-w-[75%] p-4 rounded-3xl shadow-sm relative group ${isMe ? 'bg-gradient-to-r from-pink-500 to-indigo-600 text-white rounded-tr-none' : 'bg-white dark:bg-slate-800 text-slate-800 dark:text-slate-200 rounded-tl-none border border-slate-100 dark:border-slate-700'}`}>
                   <p className="font-medium text-sm leading-relaxed">{msg.text}</p>
                   <span className={`text-[10px] font-bold absolute bottom-[-20px] ${isMe ? 'right-1 text-slate-400' : 'left-1 text-slate-400'} uppercase`}>{msg.timestamp}</span>
                 </div>
               </motion.div>
             );
           })}
           {isTyping && (
             <div className="bg-white dark:bg-slate-800 p-4 rounded-3xl rounded-tl-none border border-slate-100 dark:border-slate-700 flex gap-1 w-fit">
               <span className="w-1.5 h-1.5 bg-slate-300 rounded-full animate-bounce"></span>
               <span className="w-1.5 h-1.5 bg-slate-300 rounded-full animate-bounce delay-100"></span>
               <span className="w-1.5 h-1.5 bg-slate-300 rounded-full animate-bounce delay-200"></span>
             </div>
           )}
        </div>

        <div className="p-6 border-t border-slate-100 dark:border-slate-800 bg-white/50 dark:bg-slate-900/50 backdrop-blur-md">
          <form onSubmit={handleSend} className="flex items-center gap-4 bg-slate-50 dark:bg-slate-800 p-2 rounded-3xl border border-slate-200 dark:border-slate-700">
            <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileUpload} />
            <button type="button" onClick={() => fileInputRef.current?.click()} className="p-3 rounded-2xl hover:bg-white dark:hover:bg-slate-700 transition-colors text-slate-400 hover:text-pink-500"><AttachmentIcon size={20} /></button>
            <input type="text" placeholder="Escribe un mensaje..." value={inputText} onChange={e => setInputText(e.target.value)} className="flex-1 bg-transparent border-none outline-none font-medium text-sm px-2 text-slate-900 dark:text-white placeholder:text-slate-400" />
            <button type="submit" disabled={!inputText.trim()} className="bg-pink-500 text-white p-4 rounded-2xl shadow-lg hover:bg-pink-600 transition-all disabled:opacity-50"><Send size={20} /></button>
          </form>
        </div>
      </div>
    </div>
  );
};

