            </div>
          </div>
        </div>
      </div>

      <Lightbox 
        images={property.images} 
        initialIndex={lightbox.index} 
        isOpen={lightbox.isOpen} 
        onClose={() => setLightbox({ ...lightbox, isOpen: false })} 
      />
    </div>
  );
};

