const AuthPage = ({ mode }: { mode: 'login' | 'register' }) => {
  const { setUser } = useApp();
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const found = MOCK_USERS.find(u => u.email === email && (u.password === password || password === 'demo'));
    if (found) {
      setUser(found);
      if (found.role === UserRole.SUPERADMIN) navigate('/admin');
      else if (found.role === UserRole.HOST) navigate('/host');
      else navigate('/');
    } else {
      setError('Credenciales inválidas. Por favor, verifica el email y la contraseña.');
    }
  };

  return (
    <div className="min-h-[calc(100vh-80px)] flex items-center justify-center p-6 bg-slate-50 dark:bg-slate-950">
      <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="w-full max-w-md glass-card p-10 rounded-[3.5rem] shadow-2xl border-none">
        <div className="text-center mb-10">
          <div className="bg-gradient-to-br from-pink-500 to-indigo-600 w-16 h-16 rounded-[1.5rem] flex items-center justify-center text-white mx-auto mb-6 shadow-xl"><Lock size={32} /></div>
