  const [messages, setMessages] = useState<{ [key: string]: ChatMessage[] }>({
    '1': [
      { id: 'm1', senderId: 'u-host', text: '¡Hola! He visto tu interés en la villa.', timestamp: '18:24', type: 'text' },
      { id: 'm2', senderId: 'u-guest', text: 'Hola, sí, me gustaría saber si la villa tiene cuna.', timestamp: '18:30', type: 'text' },
    ]
  });

  const activeThread = threads.find(t => t.id === activeThreadId);
  const activeMessages = messages[activeThreadId] || [];

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [activeMessages, isTyping]);

  const handleSend = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!inputText.trim()) return;

    const newMessage: ChatMessage = {
      id: Math.random().toString(36).substr(2, 9),
      senderId: user?.id || 'u-guest',
      text: inputText,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      type: 'text'
    };

    setMessages(prev => ({ ...prev, [activeThreadId]: [...(prev[activeThreadId] || []), newMessage] }));
    setInputText('');

    setTimeout(() => {
      setIsTyping(true);
      setTimeout(() => {
        setIsTyping(false);
        const reply: ChatMessage = {
          id: Math.random().toString(36).substr(2, 9),
          senderId: activeThread?.participantId || 'bot',
          text: `Recibido. Te informo en un momento.`,
          timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
          type: 'text'
        };
        setMessages(prev => ({ ...prev, [activeThreadId]: [...(prev[activeThreadId] || []), reply] }));
      }, 2000);
    }, 1000);
  };

  return (
    <div className="max-w-[1440px] mx-auto px-6 py-12 flex gap-8 h-[calc(100vh-100px)]">
      <div className="w-1/3 glass-card rounded-[2.5rem] border shadow-2xl flex flex-col overflow-hidden">
        <div className="p-8 border-b dark:border-slate-800">
          <h2 className="text-2xl font-black mb-6">Mensajes</h2>
          <div className="relative">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input type="text" placeholder="Buscar..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full py-3 pl-12 pr-4 rounded-2xl bg-slate-50 dark:bg-slate-800 outline-none" />
          </div>
        </div>
        <div className="flex-1 overflow-y-auto">
          {threads.map(t => (
            <button key={t.id} onClick={() => setActiveThreadId(t.id)} className={`w-full p-6 flex items-center gap-4 border-b dark:border-slate-800 transition-colors ${activeThreadId === t.id ? 'bg-slate-50 dark:bg-slate-800' : 'hover:bg-slate-50/50'}`}>
              <div className="relative">
                <img src={t.avatar} className="w-12 h-12 rounded-full" alt="" />
                <span className={`absolute bottom-0 right-0 w-3 h-3 rounded-full border-2 border-white dark:border-slate-800 ${t.status === 'En línea' ? 'bg-green-500' : 'bg-slate-400'}`}></span>
              </div>
              <div className="text-left flex-1">
                <h4 className="font-bold">{t.name}</h4>
                <p className="text-sm text-slate-500 truncate">{t.lastMessage}</p>
              </div>
            </button>
          ))}
        </div>
      </div>

      <div className="flex-1 glass-card rounded-[2.5rem] border shadow-2xl flex flex-col overflow-hidden">
        <div className="p-6 border-b dark:border-slate-800 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <img src={activeThread?.avatar} className="w-12 h-12 rounded-full" alt="" />
            <div>
              <h3 className="font-bold">{activeThread?.name}</h3>
              <p className="text-[10px] font-black uppercase text-green-500">{activeThread?.status}</p>
            </div>
          </div>
          <div className="flex gap-4">
             <button className="p-3 rounded-xl bg-slate-50 dark:bg-slate-800"><Phone size={20} /></button>
             <button className="p-3 rounded-xl bg-slate-50 dark:bg-slate-800"><Video size={20} /></button>
          </div>
        </div>
        <div className="flex-1 p-8 overflow-y-auto space-y-6">
           {activeMessages.map(msg => {
             const isMe = msg.senderId === user?.id;
             return (
               <div key={msg.id} className={`flex ${isMe ? 'justify-end' : 'justify-start'}`}>
                 <div className={`max-w-[70%] p-4 rounded-3xl ${isMe ? 'bg-indigo-600 text-white rounded-tr-none' : 'bg-slate-100 dark:bg-slate-800 rounded-tl-none'}`}>
                   <p className="text-sm">{msg.text}</p>
                   <span className="text-[10px] block mt-1 opacity-50 uppercase font-black">{msg.timestamp}</span>
                 </div>
               </div>
             );
           })}
        </div>
        <form onSubmit={handleSend} className="p-6 border-t dark:border-slate-800 flex gap-4">
          <input type="text" placeholder="Escribe un mensaje..." value={inputText} onChange={e => setInputText(e.target.value)} className="flex-1 bg-slate-50 dark:bg-slate-800 p-4 rounded-2xl outline-none" />
          <button type="submit" className="bg-pink-500 text-white p-4 rounded-2xl"><Send size={24} /></button>
        </form>
      </div>
    </div>
  );
};

