const AuthPage = ({ mode }: { mode: 'login' | 'register' }) => {
  const { setUser } = useApp();
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const found = MOCK_USERS.find(u => u.email === email && (u.password === password || password === 'demo'));
    if (found) {
      setUser(found);
      if (found.role === UserRole.SUPERADMIN) navigate('/admin');
      else if (found.role === UserRole.HOST) navigate('/host');
      else navigate('/');
    } else {
      setError('Credenciales inválidas. Por favor, verifica el email y la contraseña.');
    }
  };

  return (
    <div className="min-h-[calc(100vh-80px)] flex items-center justify-center p-6 bg-slate-50 dark:bg-slate-950">
      <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="w-full max-w-md glass-card p-10 rounded-[3.5rem] shadow-2xl border-none">
        <div className="text-center mb-10">
          <div className="bg-gradient-to-br from-pink-500 to-indigo-600 w-16 h-16 rounded-[1.5rem] flex items-center justify-center text-white mx-auto mb-6 shadow-xl"><Lock size={32} /></div>
          <h2 className="text-3xl font-black mb-2">{mode === 'login' ? 'Bienvenido a Havenly' : 'Crea tu cuenta'}</h2>
          <p className="text-slate-500 font-medium">Gestiona tus vacaciones de forma inteligente</p>
        </div>
        {error && <p className="bg-red-50 text-red-500 p-4 rounded-2xl mb-6 text-sm font-bold">{error}</p>}
        <form onSubmit={handleLogin} className="space-y-6">
          <div>
            <label className="block text-[10px] font-black uppercase text-slate-400 mb-2 ml-1">Email</label>
            <input type="email" required value={email} onChange={e => setEmail(e.target.value)} placeholder="tu@email.com" className="w-full p-4 rounded-2xl border dark:border-slate-800 bg-white dark:bg-slate-900 outline-none font-bold" />
          </div>
          <div>
            <label className="block text-[10px] font-black uppercase text-slate-400 mb-2 ml-1">Contraseña</label>
