          </div>
          <button type="submit" className="w-full py-5 rounded-3xl bg-indigo-600 text-white font-black text-lg shadow-xl hover:bg-indigo-700 transition-all active:scale-95">Entrar</button>
        </form>
        <div className="mt-8 text-center text-sm font-bold text-slate-400">
           {mode === 'login' ? '¿No tienes cuenta? ' : '¿Ya tienes cuenta? '}
           <Link to={mode === 'login' ? '/register' : '/login'} className="text-pink-500 hover:underline">Hazlo aquí</Link>
        </div>
      </motion.div>
    </div>
  );
