const AdminPropertiesView = () => {
  const { properties, setProperties, user } = useApp();
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  // New Property Form State
  const [formData, setFormData] = useState({
    title: '',
    location: '',
    pricePerNight: '',
    category: 'Villa',
    maxGuests: '4',
    description: '',
    imageUrl: 'https://images.unsplash.com/photo-1613490493576-7fde63acd811?q=80&w=1000'
  });

  const filtered = properties.filter(p => p.title.toLowerCase().includes(searchTerm.toLowerCase()) || p.location.toLowerCase().includes(searchTerm.toLowerCase()));

  const handleDelete = (id: string) => {
    if (confirm("¿Seguro que quieres eliminar esta propiedad?")) {
      setProperties(prev => prev.filter(p => p.id !== id));
    }
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingId) {
      setProperties(prev => prev.map(p => p.id === editingId ? { 
        ...p, 
        title: formData.title, 
        location: formData.location, 
        pricePerNight: Number(formData.pricePerNight), 
        category: formData.category,
        maxGuests: Number(formData.maxGuests),
        description: formData.description
      } : p));
    } else {
      const newProperty: Property = {
        id: 'p' + Math.random().toString(36).substr(2, 5),
        hostId: user?.id || 'u-host',
        title: formData.title,
        location: formData.location,
        pricePerNight: Number(formData.pricePerNight),
        category: formData.category,
        maxGuests: Number(formData.maxGuests),
        description: formData.description,
        images: [formData.imageUrl],
        rating: 4.5,
        reviewsCount: 0,
        amenities: ['WiFi', 'Cocina'],
        status: 'available',
        taxRate: 0.1
      };
      setProperties(prev => [newProperty, ...prev]);
    }
    setIsModalOpen(false);
    setEditingId(null);
    setFormData({ title: '', location: '', pricePerNight: '', category: 'Villa', maxGuests: '4', description: '', imageUrl: 'https://images.unsplash.com/photo-1613490493576-7fde63acd811?q=80&w=1000' });
  };

  const openEdit = (p: Property) => {
    setEditingId(p.id);
    setFormData({
      title: p.title,
      location: p.location,
      pricePerNight: p.pricePerNight.toString(),
      category: p.category,
