  const visibleThreads = chatThreads.filter(t => {
      // In a real app, thread IDs or participants would be checked.
      // Here we assume threads are shared mock data but role-filtered.
      if (user?.role === UserRole.SUPERADMIN) return true;
      if (user?.role === UserRole.HOST) return t.participantId.includes('host') || t.participantId === 'u-guest';
      return t.participantId === 'u-host' || t.participantId === 'u-admin';
  });

  const activeThread = chatThreads.find(t => t.id === activeThreadId);
  const activeMessages = chatMessages.filter(m => {
      // Logic: Show messages for the active conversation
      // For mock purposes, we filter by a hardcoded mapping if thread ID matches
      if (!activeThreadId) return false;
      // In this session-based mock, we assume all messages belong to the thread context for simplicity
      return true; 
