interface AppContextType {
  user: UserType | null;
  setUser: (u: UserType | null) => void;
  siteConfig: SiteConfig;
  setSiteConfig: (c: SiteConfig) => void;
  isDark: boolean;
  toggleTheme: () => void;
  bookings: Booking[];
