              {docBase64 ? (
                <>
                  <CheckCircle size={56} className="mx-auto text-green-500" />
                  <p className="font-black text-xl mt-4 text-green-600">Documento Cargado</p>
                  <p className="text-xs text-slate-400 font-bold mt-1">Pulsa para cambiar</p>
                </>
              ) : (
                <>
                  <Upload size={56} className="mx-auto text-slate-300 dark:text-slate-700" />
                  <p className="font-black text-xl mt-4 text-slate-400 dark:text-slate-600">Haz clic para subir documento</p>
                </>
