           <input ref={fileInputRef} type="file" accept="image/*,application/pdf" onChange={handleDocUpload} className="hidden" />
           <button type="submit" className="w-full py-5 rounded-[2rem] bg-indigo-600 text-white font-black text-xl shadow-xl hover:bg-indigo-700 active:scale-95 transition-all">Enviar para Aprobación</button>
        </form>
      </Modal>
    </div>
  );
};

// --- Auth ---

const AuthPage = ({ mode }: { mode: 'login' | 'register' }) => {
  const { setUser, allUsers, setAllUsers } = useApp();
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    if (mode === 'login') {
      const found = allUsers.find(u => u.email === email && (u.password === password || password === 'demo'));
      if (found) { 
        setUser(found); 
        navigate(found.role === UserRole.SUPERADMIN ? '/admin' : found.role === UserRole.HOST ? '/host' : '/'); 
      } else {
        setError('Email o contraseña incorrectos.');
      }
    } else {
      if (allUsers.find(u => u.email === email)) {
        setError('Este email ya está en uso.');
        return;
      }
      const newUser: UserType = { id: 'u-'+Math.random().toString(36).substr(2, 5), name: name || 'Usuario', email, password, role: UserRole.GUEST, isOnline: true, idVerified: false, avatar: `https://i.pravatar.cc/150?u=${email}` };
      setAllUsers(prev => [...prev, newUser]);
      setUser(newUser);
      navigate('/');
    }
  };

  return (
    <div className="min-h-[calc(100vh-80px)] flex items-center justify-center p-6 bg-slate-50 dark:bg-slate-950 transition-colors">
      <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="w-full max-w-md glass-card p-12 rounded-[4rem] shadow-2xl border-none bg-white dark:bg-slate-900">
        <div className="text-center mb-10">
           <div className="bg-pink-500 w-16 h-16 rounded-2xl flex items-center justify-center text-white mx-auto mb-6 shadow-xl"><Lock size={32} /></div>
           <h2 className="text-4xl font-black tracking-tight">{mode === 'login' ? 'Bienvenido' : 'Únete a nosotros'}</h2>
        </div>
        {error && <p className="bg-red-50 dark:bg-red-900/30 text-red-500 p-4 rounded-2xl mb-6 text-xs font-bold border border-red-100 dark:border-red-800/50">{error}</p>}
        <form onSubmit={handleSubmit} className="space-y-6">
          {mode === 'register' && <input required type="text" placeholder="Nombre completo" value={name} onChange={e => setName(e.target.value)} className="w-full p-5 rounded-2xl bg-slate-50 dark:bg-slate-800 dark:text-white outline-none font-bold border dark:border-slate-700" />}
          <input required type="email" placeholder="Email corporativo" value={email} onChange={e => setEmail(e.target.value)} className="w-full p-5 rounded-2xl bg-slate-50 dark:bg-slate-800 dark:text-white outline-none font-bold border dark:border-slate-700" />
          <input required type="password" placeholder="Contraseña segura" value={password} onChange={e => setPassword(e.target.value)} className="w-full p-5 rounded-2xl bg-slate-50 dark:bg-slate-800 dark:text-white outline-none font-bold border dark:border-slate-700" />
          <button type="submit" className="w-full py-6 rounded-[2rem] bg-indigo-600 text-white font-black text-xl shadow-xl hover:bg-indigo-700 active:scale-95 transition-all">
            {mode === 'login' ? 'Entrar ahora' : 'Crear mi cuenta'}
          </button>
        </form>
        <div className="mt-8 text-center text-sm font-bold text-slate-500 dark:text-slate-400">
           {mode === 'login' ? '¿No tienes cuenta? ' : '¿Ya eres miembro? '}
           <Link to={mode === 'login' ? '/register' : '/login'} className="text-pink-500 hover:underline">
             {mode === 'login' ? 'Regístrate aquí' : 'Inicia sesión'}
           </Link>
        </div>
      </motion.div>
    </div>
  );
};

