const AdminPropertiesView = () => {
  const { properties, setProperties, user } = useApp();
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const isAdmin = user?.role === UserRole.SUPERADMIN;

  const [formData, setFormData] = useState({
    title: '', location: '', pricePerNight: '', category: 'Villa', maxGuests: '4', description: '', images: [] as string[], rules: [] as string[]
  });

  const [ruleInput, setRuleInput] = useState('');

  const filtered = properties.filter(p => (isAdmin || p.hostId === user?.id) && (p.title.toLowerCase().includes(searchTerm.toLowerCase()) || p.location.toLowerCase().includes(searchTerm.toLowerCase())));

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files) {
      Array.from(files).forEach(file => {
        const reader = new FileReader();
        reader.onloadend = () => setFormData(prev => ({ ...prev, images: [...prev.images, reader.result as string] }));
        reader.readAsDataURL(file);
      });
    }
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingId) {
      setProperties(prev => prev.map(p => p.id === editingId ? { ...p, ...formData, pricePerNight: Number(formData.pricePerNight), maxGuests: Number(formData.maxGuests) } : p));
    } else {
      setProperties(prev => [{ ...formData, id: 'p'+Math.random(), hostId: user!.id, rating: 4.5, reviewsCount: 0, amenities: ['WiFi', 'Cocina'], status: 'available', taxRate: 0.1, pricePerNight: Number(formData.pricePerNight), maxGuests: Number(formData.maxGuests) } as any, ...prev]);
    }
    setIsModalOpen(false);
  };

  const addRule = () => {
    if (ruleInput.trim()) {
      setFormData(prev => ({ ...prev, rules: [...prev.rules, ruleInput.trim()] }));
      setRuleInput('');
    }
  };

  const removeRule = (idx: number) => {
    setFormData(prev => ({ ...prev, rules: prev.rules.filter((_, i) => i !== idx) }));
  };

  return (
    <div className="flex-1 p-12 bg-slate-50 dark:bg-slate-950 overflow-y-auto transition-colors">
      <div className="flex justify-between items-center mb-12">
        <h1 className="text-4xl font-black">Propiedades</h1>
        <button onClick={() => { setEditingId(null); setFormData({ title: '', location: '', pricePerNight: '', category: 'Villa', maxGuests: '4', description: '', images: [], rules: [] }); setIsModalOpen(true); }} className="bg-pink-500 text-white px-8 py-4 rounded-2xl font-black shadow-xl hover:bg-pink-600 transition-colors">Nueva Propiedad</button>
      </div>
      <div className="mb-8 relative">
        <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-400" size={24} />
        <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} type="text" placeholder="Buscar por nombre o lugar..." className="w-full py-6 pl-16 pr-8 rounded-[2rem] bg-white dark:bg-slate-900 border-none outline-none font-bold text-lg shadow-xl dark:text-white transition-all focus:ring-2 ring-indigo-500" />
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {filtered.map(p => (
          <div key={p.id} className="glass-card rounded-[3rem] overflow-hidden shadow-2xl flex flex-col group border-none bg-white dark:bg-slate-900">
            <div className="relative h-48">
               <img src={p.images[0]} className="w-full h-full object-cover" alt="" />
               <div className="absolute top-4 right-4 flex gap-2">
                  <button onClick={() => { setEditingId(p.id); setFormData({ ...p, pricePerNight: p.pricePerNight.toString(), maxGuests: p.maxGuests.toString() }); setIsModalOpen(true); }} className="p-2.5 rounded-xl bg-white/20 backdrop-blur-md text-white hover:bg-white/40"><Edit size={18}/></button>
                  <button onClick={() => setProperties(prev => prev.filter(x => x.id !== p.id))} className="p-2.5 rounded-xl bg-red-500/80 backdrop-blur-md text-white hover:bg-red-600"><Trash2 size={18}/></button>
               </div>
            </div>
            <div className="p-8">
              <h3 className="text-xl font-black">{p.title}</h3>
              <p className="text-slate-500 font-bold text-xs mb-4">{p.location}</p>
              <p className="text-2xl font-black">€{p.pricePerNight}</p>
            </div>
          </div>
        ))}
        {filtered.length === 0 && <p className="col-span-full text-center py-20 font-bold text-slate-400">No se encontraron propiedades.</p>}
      </div>
      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingId ? 'Editar Propiedad' : 'Crear Propiedad'}>
        <form onSubmit={handleSave} className="space-y-6">
           <input required type="text" placeholder="Nombre Comercial" value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} className="w-full p-4 rounded-2xl bg-slate-50 dark:bg-slate-800 outline-none font-bold dark:text-white" />
           <input required type="text" placeholder="Ubicación (Ciudad, País)" value={formData.location} onChange={e => setFormData({...formData, location: e.target.value})} className="w-full p-4 rounded-2xl bg-slate-50 dark:bg-slate-800 outline-none font-bold dark:text-white" />
           <div className="grid grid-cols-2 gap-4">
              <input required type="number" placeholder="Precio / Noche" value={formData.pricePerNight} onChange={e => setFormData({...formData, pricePerNight: e.target.value})} className="w-full p-4 rounded-2xl bg-slate-50 dark:bg-slate-800 outline-none font-bold dark:text-white" />
              <input required type="number" placeholder="Huéspedes Máx" value={formData.maxGuests} onChange={e => setFormData({...formData, maxGuests: e.target.value})} className="w-full p-4 rounded-2xl bg-slate-50 dark:bg-slate-800 outline-none font-bold dark:text-white" />
           </div>

           <div className="space-y-3">
              <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Reglas del Alojamiento</label>
              <div className="flex gap-2">
                 <input type="text" value={ruleInput} onChange={e => setRuleInput(e.target.value)} placeholder="Ej: No fumar" className="flex-1 p-4 rounded-xl bg-slate-50 dark:bg-slate-800 dark:text-white font-bold outline-none" />
                 <button type="button" onClick={addRule} className="p-4 bg-indigo-600 text-white rounded-xl"><Plus size={20}/></button>
              </div>
              <div className="flex flex-wrap gap-2">
                 {formData.rules.map((r, i) => (
                   <span key={i} className="px-3 py-1.5 bg-slate-100 dark:bg-slate-800 rounded-lg text-xs font-bold flex items-center gap-2">
                     {r} <button type="button" onClick={() => removeRule(i)} className="text-red-500"><X size={14}/></button>
                   </span>
                 ))}
              </div>
           </div>

           <textarea placeholder="Descripción del alojamiento..." value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className="w-full p-4 rounded-2xl bg-slate-50 dark:bg-slate-800 outline-none font-medium min-h-[100px] dark:text-white" />
           <div className="flex items-center gap-4">
              <button type="button" onClick={() => fileInputRef.current?.click()} className="flex items-center gap-2 px-6 py-3 rounded-xl bg-indigo-600 text-white font-black text-xs hover:bg-indigo-700 transition-all"><Upload size={16}/> Subir Fotos</button>
              <input ref={fileInputRef} type="file" multiple accept="image/*" className="hidden" onChange={handleFileUpload} />
              <p className="text-xs font-bold text-slate-400">{formData.images.length} fotos seleccionadas</p>
           </div>
           <button type="submit" className="w-full py-5 rounded-[2rem] bg-indigo-600 text-white font-black text-xl shadow-xl hover:bg-indigo-700 active:scale-95 transition-all">Guardar Propiedad</button>
        </form>
      </Modal>
    </div>
  );
};

