const PropertyDetailPage = () => {
  const { id } = useParams();
  const location = useLocation();
  const { properties, user, verifications, addVerification, setBookings } = useApp();
  const navigate = useNavigate();
  const [advice, setAdvice] = useState<string>('');
  const [loadingAdvice, setLoadingAdvice] = useState(false);
  const [isLightboxOpen, setIsLightboxOpen] = useState(false);
  const [lightboxIndex, setLightboxIndex] = useState(0);
  const [isVerificationModalOpen, setIsVerificationModalOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [docBase64, setDocBase64] = useState<string | null>(null);

  const [checkIn, setCheckIn] = useState('');
  const [checkOut, setCheckOut] = useState('');
  const [guestsCount, setGuestsCount] = useState(1);

  const property = properties.find(p => p.id === id);

  const hostVerification = user ? verifications.find(v => v.userId === user.id && v.hostId === property?.hostId) : null;
  const isVerifiedForThisHost = hostVerification?.status === 'approved';
  const hasPendingVerification = hostVerification?.status === 'pending';

  const calculateTotalPrice = () => {
    if (!checkIn || !checkOut || !property) return 0;
    const start = new Date(checkIn);
    const end = new Date(checkOut);
    const diff = end.getTime() - start.getTime();
    const nights = Math.ceil(diff / (1000 * 60 * 60 * 24));
    return nights > 0 ? nights * property.pricePerNight : 0;
  };

  const handleBooking = () => {
    if (!user) return navigate('/login', { state: { from: location.pathname } });
    const total = calculateTotalPrice();
    if (total <= 0) return alert('Por favor selecciona fechas válidas.');

    setBookings(prev => [...prev, { 
      id: 'b-'+Math.random().toString(36).substr(2, 5), 
      propertyId: property!.id, 
      guestId: user.id, 
      checkIn, checkOut, 
      totalPrice: total, 
      taxAmount: total*0.1, 
      commissionAmount: total*0.05, 
      status: 'pending', 
      guestsCount 
    }]);
    alert('¡Reserva enviada al anfitrión!');
    navigate('/settings');
  };

  const handleGetAdvice = async () => {
    if (!property) return;
    setLoadingAdvice(true);
    setAdvice('');
    try {
      const result = await getPropertyAiAdvice(property.title, "Busco una escapada cómoda y con encanto.");
      setAdvice(result || "Este lugar es ideal para tus necesidades.");
    } catch (e) {
      setAdvice("No pudimos conectar con el conserje en este momento.");
    } finally {
      setLoadingAdvice(false);
    }
  };

  const handleDocUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setDocBase64(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleSubmitVerification = (e: React.FormEvent) => {
    e.preventDefault();
    if (!docBase64) return alert('Debes subir un documento antes de enviar.');
    addVerification({ 
      id: 'v'+Math.random().toString(36).substr(2, 9), 
      userId: user!.id, 
      hostId: property!.hostId, 
      status: 'pending', 
      documentUrl: docBase64, 
      submittedAt: new Date().toLocaleDateString() 
    });
    setIsVerificationModalOpen(false);
    setDocBase64(null);
  };

  if (!property) return <div className="p-40 text-center font-black text-5xl opacity-10">404</div>;

  return (
    <div className="max-w-[1440px] mx-auto px-12 py-16 bg-slate-50 dark:bg-slate-950 transition-colors">
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-20">
        <div className="space-y-8">
           <div className="relative group">
              <img src={property.images[0]} onClick={() => { setLightboxIndex(0); setIsLightboxOpen(true); }} className="w-full aspect-[4/3] rounded-[3.5rem] object-cover shadow-2xl cursor-pointer transition-transform group-hover:scale-[1.01]" alt="" />
              <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 rounded-[3.5rem] pointer-events-none transition-all"></div>
           </div>
           <div className="grid grid-cols-4 gap-4">
             {property.images.slice(1, 5).map((img, i) => (
               <img key={i} src={img} onClick={() => { setLightboxIndex(i+1); setIsLightboxOpen(true); }} className="w-full aspect-square rounded-3xl object-cover cursor-pointer hover:opacity-80 transition-all border dark:border-slate-800" alt="" />
             ))}
           </div>
           <Lightbox images={property.images} initialIndex={lightboxIndex} isOpen={isLightboxOpen} onClose={() => setIsLightboxOpen(false)} />

           <div className="glass-card p-10 rounded-[3rem] bg-white dark:bg-slate-900 shadow-xl space-y-6">
              <h3 className="text-2xl font-black text-slate-900 dark:text-white">Reglas del alojamiento</h3>
              <ul className="space-y-4">
                {property.rules && property.rules.length > 0 ? (
                  property.rules.map((rule, idx) => (
                    <li key={idx} className="flex items-center gap-3 text-slate-600 dark:text-slate-300 font-bold">
                       <CheckCircle size={18} className="text-pink-500" /> {rule}
                    </li>
                  ))
                ) : (
                  <li className="text-slate-400 font-bold italic">No hay reglas específicas definidas por el anfitrión.</li>
                )}
              </ul>
           </div>
        </div>

        <div className="space-y-12">
          <div>
            <div className="flex items-center gap-3 mb-4">
               <span className="bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest">{property.category}</span>
               <span className="bg-yellow-50 dark:bg-yellow-900/30 text-yellow-600 dark:text-yellow-400 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest flex items-center gap-1"><Star size={12} fill="currentColor"/> {property.rating}</span>
            </div>
            <h1 className="text-6xl font-black mb-6 tracking-tight text-slate-900 dark:text-white leading-tight">{property.title}</h1>
            <p className="text-xl text-slate-500 dark:text-slate-400 font-bold mb-8 flex items-center gap-2"><MapPin size={24} className="text-pink-500" /> {property.location}</p>
            <div className="flex flex-wrap gap-4">
               {property.amenities.map(a => (
                 <span key={a} className="flex items-center gap-2 px-6 py-3 rounded-2xl bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 text-xs font-black uppercase shadow-sm">
                   {a.toLowerCase().includes('wifi') && <Wifi size={16} className="text-indigo-500" />}
                   {a.toLowerCase().includes('piscina') && <Waves size={16} className="text-indigo-500" />}
                   {a.toLowerCase().includes('aire') && <Snowflake size={16} className="text-indigo-500" />}
                   {a.toLowerCase().includes('cocina') && <Utensils size={16} className="text-indigo-500" />}
                   {a.toLowerCase().includes('parking') && <Car size={16} className="text-indigo-500" />}
                   {a}
                 </span>
               ))}
            </div>
          </div>

          <div className="glass-card p-12 rounded-[4rem] shadow-2xl bg-white dark:bg-slate-900 border-none flex flex-col gap-8">
            <div className="flex justify-between items-end border-b dark:border-slate-800 pb-6">
               <div>
                  <p className="text-4xl font-black text-slate-900 dark:text-white">€{property.pricePerNight}</p>
                  <p className="text-xs font-black uppercase text-slate-400">por noche</p>
               </div>
               <div className="text-right">
                  <p className="text-3xl font-black text-indigo-600 dark:text-indigo-400">€{calculateTotalPrice()}</p>
                  <p className="text-xs font-black uppercase text-slate-400">estancia total</p>
               </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
               <div className="space-y-2">
                 <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Entrada</label>
                 <input type="date" value={checkIn} onChange={e => setCheckIn(e.target.value)} className="w-full p-4 rounded-2xl bg-slate-50 dark:bg-slate-800 dark:text-white outline-none font-bold border dark:border-slate-700" />
               </div>
               <div className="space-y-2">
                 <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Salida</label>
                 <input type="date" value={checkOut} onChange={e => setCheckOut(e.target.value)} className="w-full p-4 rounded-2xl bg-slate-50 dark:bg-slate-800 dark:text-white outline-none font-bold border dark:border-slate-700" />
               </div>
               <div className="col-span-2 space-y-2">
                 <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Huéspedes</label>
                 <select value={guestsCount} onChange={e => setGuestsCount(Number(e.target.value))} className="w-full p-4 rounded-2xl bg-slate-50 dark:bg-slate-800 dark:text-white outline-none font-bold border dark:border-slate-700 appearance-none">
                   {[...Array(property.maxGuests)].map((_, i) => <option key={i+1} value={i+1}>{i+1} Huésped{i > 0 ? 'es' : ''}</option>)}
                 </select>
               </div>
            </div>
            {isVerifiedForThisHost ? (
              <button onClick={handleBooking} className="w-full py-6 rounded-[2.5rem] bg-pink-500 text-white font-black text-2xl shadow-xl hover:bg-pink-600 active:scale-95 transition-all">Reservar ahora</button>
            ) : (
              <button onClick={() => user ? setIsVerificationModalOpen(true) : navigate('/login', { state: { from: location.pathname } })} disabled={hasPendingVerification} className="w-full py-6 rounded-[2.5rem] bg-indigo-600 text-white font-black text-xl shadow-xl hover:bg-indigo-700 active:scale-95 transition-all disabled:opacity-50 flex items-center justify-center gap-3">
                {hasPendingVerification ? <><Clock size={24}/> Verificación Pendiente</> : <><ShieldAlert size={24}/> Verificar ID para Reservar</>}
              </button>
            )}
          </div>

          <div className="space-y-6">
            <h3 className="text-3xl font-black text-slate-900 dark:text-white">Información detallada</h3>
            <p className="text-slate-600 dark:text-slate-400 text-xl leading-relaxed font-medium">{property.description}</p>
          </div>

          <div className="glass-card p-10 rounded-[3.5rem] bg-indigo-600 text-white shadow-2xl relative overflow-hidden group border-none">
            <div className="relative z-10">
               <div className="flex items-center justify-between mb-6">
                  <h3 className="text-2xl font-black flex items-center gap-3"><Zap size={28} /> Concierge IA</h3>
                  <button onClick={handleGetAdvice} disabled={loadingAdvice} className="bg-white text-indigo-600 px-6 py-3 rounded-2xl font-black text-xs hover:bg-slate-100 transition-all disabled:animate-pulse shadow-xl">
                    {loadingAdvice ? 'Escaneando...' : 'Pedir Consejo'}
                  </button>
               </div>
               {advice && (
                 <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="bg-white/10 p-6 rounded-[2rem] backdrop-blur-md border border-white/20">
                   <p className="italic font-medium text-lg leading-relaxed">"{advice}"</p>
