           </p>
           <div onClick={() => fileInputRef.current?.click()} className={`border-4 border-dashed rounded-[2.5rem] p-12 text-center cursor-pointer transition-all ${docBase64 ? 'border-green-500 bg-green-50 dark:bg-green-900/10' : 'border-slate-200 dark:border-slate-800 hover:border-indigo-500/30'}`}>
              {docBase64 ? (
                <>
                  <CheckCircle size={56} className="mx-auto text-green-500" />
