              <div className="flex items-center gap-1 font-black text-slate-800 dark:text-slate-100 bg-slate-50 dark:bg-slate-900 px-4 py-2 rounded-2xl border border-slate-100 dark:border-slate-800 text-sm">
                <Star size={16} className="fill-amber-400 text-amber-400" /> {property.rating} · <span className="text-slate-400 ml-1">{property.reviewsCount} reseñas</span>
              </div>
            </div>
            <h1 className="text-5xl md:text-7xl font-black mb-6 tracking-tighter text-slate-900 dark:text-white leading-tight">{property.title}</h1>
            <p className="text-xl text-slate-500 dark:text-slate-400 font-bold mb-10 flex items-center gap-2"><MapPin size={22} className="text-rose-500" /> {property.location}</p>

            <div className="flex flex-wrap gap-4">
              {property.amenities.map(a => (
                <div key={a} className="flex items-center gap-3 px-6 py-4 rounded-3xl bg-slate-50 dark:bg-slate-900 border border-slate-100 dark:border-slate-800 group hover:border-indigo-200 transition-colors">
                  <div className="text-indigo-600 group-hover:scale-110 transition-transform"><CheckCircle size={18} /></div>
