          <div onClick={() => fileInputRef.current?.click()} className={`border-4 border-dashed rounded-[2.5rem] p-16 text-center cursor-pointer transition-all hover:bg-slate-50 dark:hover:bg-slate-800/50 ${docBase64 ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/10' : 'border-slate-100 dark:border-slate-800'}`}>
