const PropertyDetailPage = () => {
  const { id } = useParams();
  const location = useLocation();
  const { properties, user, verifications, addVerification, setBookings } = useApp();
  const navigate = useNavigate();
  const [advice, setAdvice] = useState<string>('');
  const [loadingAdvice, setLoadingAdvice] = useState(false);
  const [isLightboxOpen, setIsLightboxOpen] = useState(false);
  const [lightboxIndex, setLightboxIndex] = useState(0);
  const [isVerificationModalOpen, setIsVerificationModalOpen] = useState(false);
  const [isPaymentModalOpen, setIsPaymentModalOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [docBase64, setDocBase64] = useState<string | null>(null);
  const [checkIn, setCheckIn] = useState('');
  const [checkOut, setCheckOut] = useState('');
  const [guestsCount, setGuestsCount] = useState(1);
  const property = properties.find(p => p.id === id);

  useEffect(() => {
    window.scrollTo(0, 0);
  }, [id]);

  const hostVerification = user && property ? verifications.find(v => v.userId === user.id && v.hostId === property.hostId) : null;
  const isActuallyVerified = user?.idVerified || hostVerification?.status === 'approved';
  const hasPendingVerification = !user?.idVerified && hostVerification?.status === 'pending';

  const calculateTotalPrice = () => {
    if (!checkIn || !checkOut || !property) return 0;
    const start = new Date(checkIn);
    const end = new Date(checkOut);
    const nights = Math.ceil((end.getTime() - start.getTime()) / (1000 * 60 * 60 * 24));
    return nights > 0 ? nights * property.pricePerNight : 0;
  };

  const handleBookingClick = () => {
    if (!user) return navigate('/login', { state: { from: location.pathname } });
    const total = calculateTotalPrice();
    if (total <= 0) return alert('Por favor selecciona fechas válidas.');
    setIsPaymentModalOpen(true);
  };

  const onPaymentConfirmed = () => {
    const total = calculateTotalPrice();
    const newBooking: Booking = { 
      id: 'b-'+Math.random().toString(36).substr(2, 5), 
      propertyId: property!.id, 
      guestId: user!.id, 
      checkIn, 
      checkOut, 
      totalPrice: total, 
      taxAmount: total*0.1, 
      commissionAmount: total*0.05, 
      status: 'pending', 
      guestsCount 
    };
    setBookings(prev => [...prev, newBooking]);
    alert('¡Pago enviado con éxito! Tu reserva está ahora pendiente de aprobación por el anfitrión.');
    navigate('/settings');
  };

  const handleGetAdvice = async () => {
    if (!property) return;
    setLoadingAdvice(true);
    setAdvice('');
    try {
      const result = await getPropertyAiAdvice(property.title, "Busco una escapada cómoda y con encanto.");
      setAdvice(result || "Este lugar es ideal para tus necesidades.");
    } catch (e) { setAdvice("No pudimos conectar con el conserje en este momento."); } finally { setLoadingAdvice(false); }
  };

  const handleDocUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setDocBase64(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleSubmitVerification = (e: React.FormEvent) => {
    e.preventDefault();
    if (!docBase64) return alert('Debes subir un documento antes de enviar.');
    addVerification({ id: 'v'+Math.random().toString(36).substr(2, 9), userId: user!.id, hostId: property!.hostId, status: 'pending', documentUrl: docBase64, submittedAt: new Date().toLocaleDateString() });
    setIsVerificationModalOpen(false);
    setDocBase64(null);
  };

  if (!property) return <div className="p-40 text-center font-black text-5xl opacity-10 uppercase tracking-tighter">Propiedad no encontrada</div>;

  return (
    <div className="max-w-[1440px] mx-auto px-6 py-24">
      {/* Detail Gallery */}
      <div className="grid grid-cols-1 md:grid-cols-4 md:grid-rows-2 gap-4 h-[500px] md:h-[650px] mb-12 rounded-[3.5rem] overflow-hidden shadow-2xl relative">
        <div className="md:col-span-2 md:row-span-2 relative group cursor-pointer" onClick={() => { setLightboxIndex(0); setIsLightboxOpen(true); }}>
           <img src={property.images[0]} className="w-full h-full object-cover transition-transform group-hover:scale-105 duration-700" alt="" />
           <div className="absolute inset-0 bg-black/10 group-hover:bg-transparent transition-colors" />
        </div>
        {property.images.slice(1, 5).map((img, i) => (
          <div key={i} className="relative group cursor-pointer overflow-hidden" onClick={() => { setLightboxIndex(i+1); setIsLightboxOpen(true); }}>
            <img src={img} className="w-full h-full object-cover transition-transform group-hover:scale-110 duration-700" alt="" />
            <div className="absolute inset-0 bg-black/10 group-hover:bg-transparent transition-colors" />
          </div>
        ))}
        <Button variant="secondary" size="sm" className="absolute bottom-8 right-8 !bg-white/80 !backdrop-blur-md border-none rounded-xl" onClick={() => setIsLightboxOpen(true)}>
           <ImageIcon size={16} className="mr-2" /> Ver todas las fotos
        </Button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-16">
