const AuthPage = ({ mode }: { mode: 'login' | 'register' }) => {
  const { setUser, allUsers, setAllUsers } = useApp();
  const navigate = useNavigate();
  const location = useLocation();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    const redirectPath = location.state?.from || '/';
    const inputEmail = email.trim().toLowerCase();

    if (mode === 'login') {
      const found = allUsers.find(u => u.email.trim().toLowerCase() === inputEmail && (u.password === password || password === 'demo'));
      if (found) { 
        setUser(found); 
        if (found.role === UserRole.SUPERADMIN) navigate('/admin');
        else if (found.role === UserRole.HOST) navigate('/host');
        else navigate(redirectPath);
      } else { setError('Credenciales no válidas.'); }
    } else {
      if (allUsers.find(u => u.email.trim().toLowerCase() === inputEmail)) { setError('El email ya está en uso.'); return; }
      const newUser: UserType = { id: 'u-'+Math.random().toString(36).substr(2, 5), name: name || 'Viajero', email: inputEmail, password, role: UserRole.GUEST, isOnline: true, idVerified: false, avatar: `https://i.pravatar.cc/150?u=${inputEmail}` };
      setAllUsers(prev => [...prev, newUser]);
      setUser(newUser);
      navigate(redirectPath);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-6 bg-slate-50 dark:bg-[#020617]">
      <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} className="w-full max-w-md space-y-12">
        <div className="text-center space-y-4">
           <div className="bg-indigo-600 w-20 h-20 rounded-[2rem] flex items-center justify-center text-white mx-auto shadow-2xl shadow-indigo-200 dark:shadow-none floating"><Compass size={40} /></div>
           <h2 className="text-4xl font-black tracking-tighter dark:text-white uppercase">Havenly</h2>
           <p className="text-slate-400 font-bold text-sm tracking-widest uppercase">Plataforma de Alquiler Elite</p>
        </div>

        <div className="glass-card p-10 rounded-[3rem] bg-white dark:bg-slate-900 shadow-2xl border-none">
          {error && <p className="bg-red-50 text-red-500 p-4 rounded-2xl mb-8 text-xs font-black text-center border border-red-100">{error}</p>}
          <form onSubmit={handleSubmit} className="space-y-6">
            {mode === 'register' && (
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-1 tracking-widest">Nombre Completo</label>
                <input required type="text" value={name} onChange={e => setName(e.target.value)} className="w-full p-5 rounded-2xl bg-slate-50 dark:bg-slate-800 dark:text-white outline-none font-bold border border-slate-100 dark:border-slate-700" />
              </div>
            )}
            <div className="space-y-2">
              <label className="text-[10px] font-black uppercase text-slate-400 ml-1 tracking-widest">Correo Electrónico</label>
              <input required type="email" value={email} onChange={e => setEmail(e.target.value)} className="w-full p-5 rounded-2xl bg-slate-50 dark:bg-slate-800 dark:text-white outline-none font-bold border border-slate-100 dark:border-slate-700" />
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black uppercase text-slate-400 ml-1 tracking-widest">Contraseña</label>
              <div className="relative">
                <input required type={showPassword ? "text" : "password"} value={password} onChange={e => setPassword(e.target.value)} className="w-full p-5 rounded-2xl bg-slate-50 dark:bg-slate-800 dark:text-white outline-none font-bold border border-slate-100 dark:border-slate-700 pr-14" />
                <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-400 hover:text-indigo-600 transition-colors">
                  {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
                </button>
              </div>
            </div>
            <Button type="submit" variant="primary" size="lg" className="w-full !rounded-[1.5rem] !py-5 shadow-indigo-200">
               {mode === 'login' ? 'Iniciar Sesión' : 'Crear Cuenta'}
            </Button>
          </form>

          <div className="mt-8 text-center">
             <Link to={mode === 'login' ? '/register' : '/login'} state={location.state} className="text-indigo-600 font-black text-sm hover:underline">
               {mode === 'login' ? '¿No tienes cuenta? Regístrate' : '¿Ya eres miembro? Accede'}
             </Link>
          </div>
        </div>
      </motion.div>
    </div>
  );
};

