const Lightbox = ({ images, initialIndex, isOpen, onClose }: { images: string[], initialIndex: number, isOpen: boolean, onClose: () => void }) => {
  const [currentIndex, setCurrentIndex] = useState(initialIndex);
  useEffect(() => { setCurrentIndex(initialIndex); }, [initialIndex]);
  if (!isOpen) return null;
  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[300] bg-slate-950/95 flex flex-col items-center justify-center p-4">
      <button onClick={onClose} className="absolute top-8 right-8 text-white p-4 hover:bg-white/10 rounded-full transition-all z-[310]"><X size={32} /></button>
      <div className="relative w-full max-w-6xl h-full flex items-center justify-center">
        <button onClick={() => setCurrentIndex((prev) => (prev - 1 + images.length) % images.length)} className="absolute left-0 p-4 bg-white/5 text-white rounded-full hover:bg-white/10 transition-all z-[310]"><ChevronLeft size={48} /></button>
        <motion.img key={currentIndex} initial={{ opacity: 0, scale: 0.9, rotate: -2 }} animate={{ opacity: 1, scale: 1, rotate: 0 }} src={images[currentIndex]} className="max-h-[85vh] w-auto rounded-[3rem] shadow-2xl object-contain border border-white/10" />
        <button onClick={() => setCurrentIndex((prev) => (prev + 1) % images.length)} className="absolute right-0 p-4 bg-white/5 text-white rounded-full hover:bg-white/10 transition-all z-[310]"><ChevronRightIcon size={48} /></button>
      </div>
      <div className="absolute bottom-10 flex gap-2">
        {images.map((_, i) => (
          <div key={i} className={`w-2 h-2 rounded-full transition-all ${i === currentIndex ? 'bg-white w-8' : 'bg-white/30'}`} />
        ))}
      </div>
    </motion.div>
  );
};

