      <HashRouter>
        <Routes>
          <Route path="/admin/*" element={<div className="flex bg-[#fafafa] dark:bg-zinc-950 min-h-screen"><Sidebar /><Routes><Route index element={<DashboardHome />} /><Route path="properties" element={<div className="pl-64 pt-32 text-center">Prop View</div>} /><Route path="bookings" element={<AdminBookingsView />} /><Route path="verifications" element={<div className="pl-64 pt-32 text-center">Verifications View</div>} /><Route path="chat" element={<div className="pl-64 pt-32 text-center">Chat View</div>} /><Route path="config" element={<div className="pl-64 pt-32 text-center">Config View</div>} /></Routes></div>} />
